const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) {
  staticData.contentHistory = [];
}

if (!Number.isInteger(staticData.categoryIndex)) {
  staticData.categoryIndex = 0;
}

const categories = [
  'science',
  'space',
  'animals',
  'human body',
  'psychology',
  'history',
  'technology',
  'nature',
  'geography',
  'inventions',
  'food origins',
  'language',
  'money and economics',
  'mysteries and unusual facts',
  'records and comparisons',
  'ocean',
  'weather and natural phenomena',
  'everyday objects',
  'transportation',
  'art and culture'
];

const history = staticData.contentHistory.slice(-100);

const previous = history.length
  ? history.map((x, i) => `${i + 1}. CATEGORY: ${x.category}\nTITLE: ${x.title}\nHOOK: ${x.hook}\nTOPIC: ${x.topic}`).join('\n')
  : 'No previous content exists yet.';

const output = [];

for (let i = 0; i < 10; i++) {
  const category = categories[(staticData.categoryIndex + i) % categories.length];

  const system = `You are an expert viral YouTube Shorts scriptwriter.

The channel publishes surprising, accurate and verifiable "Did You Know?" facts.

YOUR ASSIGNED CATEGORY FOR THIS VIDEO:
${category}

Return ONLY one JSON object with EXACTLY these keys:

hook - 1 short pattern-interrupt sentence and the first line of the narration.
script - FULL narration. 70-90 words. Start with the hook. Conversational, fast and punchy. Explain ONE genuinely surprising fact. End with a short question or follow-for-more line. No emojis, hashtags or stage directions.
title - maximum 90 characters and MUST end with " #Shorts".
description - 2-3 natural sentences followed by a new line containing 5 relevant hashtags.
tags - array of 8-12 lowercase keyword strings.
query - 1-2 word English stock-video search query matching the topic.
voice - exactly one of: en-US-AriaNeural, en-US-GuyNeural, en-GB-SoniaNeural.
topic - concise description of the core fact.
category - exactly the assigned category above.

CONTENT RULES:
1. The fact must be substantially different from all previous content.
2. Never reuse a previous fact with different wording.
3. Never reuse or closely imitate a previous title.
4. Never reuse a previous hook.
5. Avoid making multiple videos about the same narrow subject.
6. Stay inside the assigned category.
7. Prefer surprising facts that are easy to understand in under one minute.
8. The fact should be verifiable; do not invent statistics or fake historical claims.
9. Keep the narration suitable for approximately 35-55 seconds.
10. Do not use list-style scripts with many unrelated facts. One strong fact per video.

PREVIOUS CONTENT TO AVOID:
${previous}`;

  const body = {
    model: 'llama-3.3-70b-versatile',
    temperature: 1.05,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      {
        role: 'user',
        content: `Generate ONE completely fresh ${category} Short. It must be substantially different from every previous item. Respond with JSON only.`
      }
    ]
  };

  output.push({
    json: {
      batchNumber: i + 1,
      category,
      body
    }
  });
}

staticData.categoryIndex = (staticData.categoryIndex + 10) % categories.length;

return output;

const res = $input.first().json;
const content = res.choices && res.choices[0] && res.choices[0].message.content;

if (!content) {
  throw new Error('No content from Groq: ' + JSON.stringify(res).slice(0, 800));
}

let data;
try {
  data = JSON.parse(content);
} catch (e) {
  throw new Error('Groq did not return valid JSON: ' + content.slice(0, 800));
}

if (!data.script || !data.title || !data.hook || !data.topic) {
  throw new Error('Groq JSON missing script/title/hook/topic');
}

data.tags = Array.isArray(data.tags) ? data.tags : [];
data.voice = data.voice || 'en-US-AriaNeural';
data.query = data.query || 'abstract';
data.category = data.category || $json.category || 'general';

if (!data.title.toLowerCase().includes('#shorts')) {
  data.title = data.title.replace(/\s*$/, '') + ' #Shorts';
}

const wordCount = String(data.script).trim().split(/\s+/).length;

if (wordCount < 65 || wordCount > 100) {
  throw new Error(`SCRIPT_LENGTH_REJECTED: ${wordCount} words. Expected approximately 70-90 words.`);
}

return [{
  json: {
    ...data,
    batchNumber: $json.batchNumber,
    requestedCategory: $json.category
  }
}];

const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (!Array.isArray(staticData.contentHistory)) {
  staticData.contentHistory = [];
}

const history = staticData.contentHistory;

function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/#shorts/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function words(text) {
  return new Set(
    normalize(text)
      .split(' ')
      .filter(w => w.length > 3)
  );
}

function similarity(a, b) {
  const A = words(a);
  const B = words(b);

  if (!A.size || !B.size) return 0;

  let intersection = 0;

  for (const word of A) {
    if (B.has(word)) intersection++;
  }

  return intersection / Math.max(1, Math.min(A.size, B.size));
}

const candidate = [
  item.title,
  item.hook,
  item.topic,
  item.script
].join(' ');

for (const old of history.slice(-100)) {
  if (normalize(item.title) === normalize(old.title)) {
    throw new Error('DUPLICATE_CONTENT_REJECTED: duplicate title');
  }

  if (normalize(item.hook) === normalize(old.hook)) {
    throw new Error('DUPLICATE_CONTENT_REJECTED: duplicate hook');
  }

  if (similarity(item.topic, old.topic) >= 0.60) {
    throw new Error('DUPLICATE_CONTENT_REJECTED: very similar topic');
  }

  const oldContent = [
    old.title,
    old.hook,
    old.topic,
    old.script
  ].join(' ');

  if (similarity(candidate, oldContent) >= 0.58) {
    throw new Error('DUPLICATE_CONTENT_REJECTED: very similar content');
  }
}

for (const current of history.filter(x => x.createdAt && x.createdAt.startsWith(new Date().toISOString().slice(0, 10)))) {
  if (current.category === item.category && similarity(item.topic, current.topic) >= 0.45) {
    throw new Error('DUPLICATE_CONTENT_REJECTED: similar topic already generated today');
  }
}

history.push({
  title: item.title,
  hook: item.hook,
  topic: item.topic,
  script: item.script,
  query: item.query,
  category: item.category,
  createdAt: new Date().toISOString()
});

while (history.length > 100) history.shift();

return [{ json: item }];

const item = $input.first().json;

const runId = `${String($execution.id || Date.now())}_${item.batchNumber}`;
const runDir = `/data/${runId}`;

const job = {
  script: item.script,
  query: item.query,
  voice: item.voice
};

const jobB64 = Buffer.from(JSON.stringify(job), 'utf8').toString('base64');

return [{
  json: {
    runId,
    runDir,
    jobB64,
    title: item.title,
    description: item.description,
    tags: item.tags,
    topic: item.topic,
    category: item.category,
    batchNumber: item.batchNumber
  }
}];
